import{_ as t,c as r,a as e,am as l}from"./chunks/framework.CTSvgyA8.js";const o="/docs/assets/03userManual_hr_04_20.AwOSZ5cU.png",m=JSON.parse('{"title":"중간  /  퇴직급여 계산","description":"","frontmatter":{},"headers":[],"relativePath":"manual/manual_hr_04/hra/hra5150.md","filePath":"manual/manual_hr_04/hra/hra5150.md"}'),i={name:"manual/manual_hr_04/hra/hra5150.md"};function h(n,a,s,d,u,_){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="중간-퇴직급여-계산" tabindex="-1">중간 / 퇴직급여 계산 <a class="header-anchor" href="#중간-퇴직급여-계산" aria-label="Permalink to &quot;중간  /  퇴직급여 계산&quot;">​</a></h1><table class="no-stripe"><tr><th><strong> Program ID</strong></th><td> HRA5150</td><th><strong> Program Name</strong></th><td> 중간 / 퇴직급여 계산</td></tr><tr><th><strong> Overview</strong></th><td colspan="3"> 중간 / 퇴직급여 계산 화면</td></tr><tr><th><strong> 메뉴 경로</strong></th><td colspan="3"> 인사관리 &gt; 정산관리 &gt; 퇴직정산 &gt; 중간 / 퇴직급여 계산</td></tr></table><p><img src="'+o+'" alt="" data-zoomable="true"></p><h2 id="화면설명" tabindex="-1">화면설명 <a class="header-anchor" href="#화면설명" aria-label="Permalink to &quot;화면설명&quot;">​</a></h2><ul><li><p>중간정산 또는 퇴직정산을 산출하는 화면</p></li><li><p>중간정산은 현재 재직중인 임직원을 기준으로 산출하며, 퇴직정산은 조회된 기간에 퇴직한 임직원 목록을 표시</p></li></ul><h2 id="사용설명" tabindex="-1">사용설명 <a class="header-anchor" href="#사용설명" aria-label="Permalink to &quot;사용설명&quot;">​</a></h2><h3 id="_1-산출" tabindex="-1">1. 산출 <a class="header-anchor" href="#_1-산출" aria-label="Permalink to &quot;1. 산출&quot;">​</a></h3><ul><li>산출할 대상자에 체크하고, 정산일을 입력하고 일괄계산 버튼을 클릭하여 산출</li></ul><h3 id="_2-퇴직소득세액을-재계산" tabindex="-1">2. 퇴직소득세액을 재계산 <a class="header-anchor" href="#_2-퇴직소득세액을-재계산" aria-label="Permalink to &quot;2. 퇴직소득세액을 재계산&quot;">​</a></h3><ul><li>급여내역 또는 상여내역에 대해 수정할 수 있으며, 저장 버튼 클릭 시 퇴직소득세액을 재계산(과세 재계산에 체크 표시 일 경우)</li></ul><h3 id="_3-입력-수정" tabindex="-1">3. 입력, 수정 <a class="header-anchor" href="#_3-입력-수정" aria-label="Permalink to &quot;3. 입력, 수정&quot;">​</a></h3><ul><li>지급배수, 누진일수, 연차수당, 퇴직위로금, 제외월수, 가산월수, 국민연금전환금, 퇴직추계액을 입력 또는 수정할 수 있음</li></ul><h3 id="_4-국민연금전환금" tabindex="-1">4. 국민연금전환금 <a class="header-anchor" href="#_4-국민연금전환금" aria-label="Permalink to &quot;4. 국민연금전환금&quot;">​</a></h3><ul><li>국민연금전환금이 있을 경우 정산구분=“퇴직정산” 일 경우 가져오며, 수정이 가능</li></ul><h3 id="_5-퇴직추계액" tabindex="-1">5. 퇴직추계액 <a class="header-anchor" href="#_5-퇴직추계액" aria-label="Permalink to &quot;5. 퇴직추계액&quot;">​</a></h3><ul><li>퇴직추계액을 입력/수정 가능</li></ul><h3 id="_6-집계-반영-반영-취소" tabindex="-1">6. 집계, 반영, 반영 취소 <a class="header-anchor" href="#_6-집계-반영-반영-취소" aria-label="Permalink to &quot;6. 집계, 반영, 반영 취소&quot;">​</a></h3><ul><li>회계처리에서 전표처리내역을 집계하고, 회계반영 버튼 클릭 시 정산계산이 확정되며, 반영 취소 버튼 클릭 시 확정이 취소 됨</li></ul>',18)])])}const p=t(i,[["render",h]]);export{m as __pageData,p as default};
